{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Diphenhydramine systemic availability after oral dosing was 0.72 ± 0.08 vs IV in healthy volunteers, corresponding to 72% absolute bioavailability, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Milnacipran absolute oral bioavailability was 85 ± 3% in humans after oral administration, strongly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "In young healthy subjects, S-9780 bioavailability after oral 8 mg perindopril was 19% ± 7%, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Most high-transfer evidence molecules show direct absolute oral bioavailability values well above 20% (e.g., 42-90%), while only one molecule reports a below-threshold mean of 19%; the overall weight supports high bioavailability.",
  "evidence_gaps": [
    "One molecule (perindopril) has conflicting records: 19% in young healthy subjects vs 30% in cirrhotic patients; the disease-state record is less transferable.",
    "Some records are unspecified bioavailability type or from altered populations (elderly, cirrhosis), adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

